#!/bin/bash
mkdir -p result
(echo "int_trb_size;latency"
for i in $(seq 0 6); do
    echo -n "$((2 ** $i));"
    #make --no-print-directory spec SPECOUTDIR=result/511.povray_r_0_1120_1157_memsec_buff SPECCMD=/opt/spec/cpu2017/benchspec/CPU/511.povray_r/exe/povray_r_base.mytest-m64 SPECOPTIONS="--options 'benchmark/511.povray_r/SPEC-benchmark-ref.ini'" SPECSTDOUT="--output SPEC-benchmark-ref.stdout" SPECSTDERR="--errout SPEC-benchmark-ref.stderr" MEMSEC=memsec GEM5_CONFIG_SPEC="--maxinsts 1000000" GEM5_CONFIG_AIM_PERF="--aim-aes-enc-cycles=80 --aim-aes-dec-cycles=80 --aim-aes-enc-ii=10 --aim-aes-dec-ii=10 --aim-mac-cycles=40 --aim-mac-ii=5 --metadata-cache-size='32KiB' --metadata-cache-assoc=8 --int-merge-req --int-defrag-req --int-trb-size="$((2 ** $i)) 2> /dev/null \
    #make --no-print-directory spec SPECOUTDIR=result/519.lbm_r_0_1120_1157_memsec_buff SPECCMD=/opt/spec/cpu2017/benchspec/CPU/519.lbm_r/exe/lbm_r_base.mytest-m64 SPECOPTIONS="--options '3000 benchmark/519.lbm_r/reference.dat 0 0 benchmark/519.lbm_r/100_100_130_ldc.of'" SPECSTDOUT="--output lbm.out" SPECSTDERR="--errout lbm.err" MEMSEC=memsec GEM5_CONFIG_SPEC="--maxinsts 1000000" GEM5_CONFIG_AIM_PERF="--aim-aes-enc-cycles=80 --aim-aes-dec-cycles=80 --aim-aes-enc-ii=10 --aim-aes-dec-ii=10 --aim-mac-cycles=40 --aim-mac-ii=5 --metadata-cache-size='32KiB' --metadata-cache-assoc=8 --int-merge-req --int-defrag-req --int-trb-size="$((2 ** $i)) 2> /dev/null \
    make --no-print-directory spec SPECOUTDIR=result/557.xz_r_2_1120_1157_memsec_basic SPECCMD=/opt/spec/cpu2017/benchspec/CPU/557.xz_r/exe/xz_r_base.mytest-m64 SPECOPTIONS="--options 'benchmark/557.xz_r/input.combined.xz 250 a841f68f38572a49d86226b7ff5baeb31bd19dc637a922a972b2e6d1257a890f6a544ecab967c313e370478c74f760eb229d4eef8a8d2836d233d3e9dd1430bf 40401484 41217675 7'" SPECSTDOUT="--output input.combined-250-7.out" SPECSTDERR="--errout input.combined-250-7.err" MEMSEC=memsec GEM5_CONFIG_SPEC="--maxinsts 1000000" GEM5_CONFIG_AIM_PERF="--aim-aes-enc-cycles=80 --aim-aes-dec-cycles=80 --aim-aes-enc-ii=10 --aim-aes-dec-ii=10 --aim-mac-ii=5 --metadata-cache-size='32KiB' --metadata-cache-assoc=8 --int-merge-req --int-defrag-req --int-trb-size="$((2 ** $i)) 2>/dev/null \
        | tail -n 1 \
        | awk '{print $NF}'
done) | tee result/int-trb-sizes-latencies
